"""Decision record transport adapters for the Desk Intelligence pullout.

A decision record is the mutable governing document for a decision (HS-127-01);
"Receipt" is reserved for immutable kernel evidence (Constitution Art. XI).
"""
from __future__ import annotations

from typing import Any

from fastapi import APIRouter, Body, HTTPException, Request
from fastapi.responses import JSONResponse

from ...db import get_database, get_observer
from ...principals import UNAUTHENTICATED
from ...services.brief_carry import RightRequired
from ...services.decision_record_service import DecisionRecordService


def build_decision_records_router(ctx: Any) -> APIRouter:
    """Expose durable decision records through the web API."""
    del ctx
    router = APIRouter(prefix="/api/decision-records", tags=["decision-records"])

    def service() -> DecisionRecordService:
        return DecisionRecordService(get_database(), observer=get_observer())

    def principal(request: Request) -> Any:
        return getattr(request.state, "principal", UNAUTHENTICATED)

    @router.get("")
    async def list_records(
        request: Request, limit: int = 50, offset: int = 0
    ) -> list[dict[str, Any]]:
        return service().list_records(principal(request), limit=limit, offset=offset)

    # Declare search before the parameterized path so FastAPI does not regard
    # "search" as a record ID.
    @router.get("/search")
    async def search_records(
        request: Request, q: str = "", limit: int = 50
    ) -> list[dict[str, Any]]:
        return service().search(principal(request), q, limit=limit)

    @router.get("/review")
    async def records_due_for_review(request: Request) -> list[dict[str, Any]]:
        return service().due_for_review(principal(request))

    @router.get("/source/{source_type}/{source_id}")
    async def records_for_source(
        source_type: str, source_id: str, request: Request
    ) -> list[dict[str, Any]]:
        return service().records_for_source(principal(request), source_type, source_id)

    @router.get("/work/{work_type}/{work_ref}")
    async def records_for_work(
        work_type: str, work_ref: str, request: Request
    ) -> list[dict[str, Any]]:
        return service().records_for_work(principal(request), work_type, work_ref)

    @router.get("/{record_id}")
    async def get_record(record_id: str, request: Request) -> dict[str, Any]:
        record = service().get(principal(request), record_id)
        if record is None:
            raise HTTPException(status_code=404, detail="decision record not found")
        return record

    # ── HS-200-13: the lifecycle verbs the recall chain needs ──────────

    @router.post("/{record_id}/supersede")
    async def supersede_record(
        record_id: str, request: Request, body: dict[str, Any] = Body(default={}),
    ) -> Any:
        """Seal ``record_id`` and name ``successor_id`` as what is current now."""
        try:
            return service().supersede(
                principal(request), record_id,
                str(body.get("successor_id") or ""), body.get("reason"),
            )
        except RightRequired as exc:
            return JSONResponse(exc.response, status_code=403)
        except KeyError as exc:
            raise HTTPException(status_code=404, detail=f"decision record not found: {exc}") from exc
        except ValueError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc

    @router.post("/{record_id}/dispute")
    async def dispute_record(
        record_id: str, request: Request, body: dict[str, Any] = Body(default={}),
    ) -> Any:
        """Mark a record DISPUTED (discoverable, never presented as current)."""
        try:
            return service().dispute(principal(request), record_id, body.get("reason"))
        except RightRequired as exc:
            return JSONResponse(exc.response, status_code=403)
        except KeyError as exc:
            raise HTTPException(status_code=404, detail=f"decision record not found: {exc}") from exc
        except ValueError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc

    @router.post("/{record_id}/carry")
    async def carry_record(
        record_id: str, request: Request, body: dict[str, Any] = Body(default={}),
    ) -> Any:
        """`Carry into brief`: queue the record, by reference, for its Project's
        next preparation (holdspeak/services/brief_carry.py)."""
        from ...services.brief_carry import carry_into_brief
        try:
            return carry_into_brief(
                get_database(), principal(request), record_id,
                project_id=body.get("project_id"),
            )
        except RightRequired as exc:
            return JSONResponse(exc.response, status_code=403)
        except KeyError as exc:
            raise HTTPException(status_code=404, detail=f"decision record not found: {exc}") from exc
        except ValueError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc

    return router
"""Durable decision record operations (HS-127-01)."""

from __future__ import annotations

import json
from datetime import UTC, date, datetime
from typing import Any
from uuid import uuid4

from holdspeak.principals import PrincipalRight
from holdspeak.services.brief_carry import require_right
from holdspeak.services.observer import (
    NullObserver,
    PipelineObserver,
    current_correlation_id,
    observe_service,
)
from holdspeak.services.service_event_ledger import ServiceEventLedger


_SOURCE_TYPES = frozenset({"meeting", "desk"})
#: HS-200-13: the record lifecycles.  ``active`` / ``published`` are CURRENT;
#: ``superseded`` names a successor; ``disputed`` is contested -- discoverable
#: on recall, never presented as current, never accented (story 13 AC2).
#: ``disputed`` is defined minimally here: a verb, a reason, a revision row;
#: no resolution workflow (out of scope: enterprise approval).
LIFECYCLES = frozenset({"active", "superseded", "published", "disputed"})
CURRENT_LIFECYCLES = frozenset({"active", "published"})
#: A supersession may seal an active OR a disputed predecessor (the usual
#: way a dispute ends is a newer decision).
_SUPERSEDABLE = frozenset({"active", "disputed"})
_EDITABLE_FIELDS = frozenset(
    {"decision_text", "rationale", "alternatives", "owner", "review_date"}
)


@observe_service
class DecisionRecordService:
    """Create and retrieve the durable canon for a decision."""

    def __init__(self, db: Any, *, observer: PipelineObserver | None = None) -> None:
        self._db = db
        self._observer = observer or NullObserver()

    def create(
        self,
        principal: Any,
        *,
        decision_text: str,
        rationale: str | None = None,
        alternatives: str | None = None,
        owner: str | None = None,
        review_date: str | None = None,
        source_type: str,
        source_id: str,
    ) -> dict[str, Any]:
        """Create a new decision record."""
        text = self._required("decision_text", decision_text)
        source_kind = self._required("source_type", source_type)
        if source_kind not in _SOURCE_TYPES:
            raise ValueError("source_type must be 'meeting' or 'desk'")
        source = self._required("source_id", source_id)
        record_id = f"record-{uuid4().hex}"
        now = datetime.now(UTC).isoformat()

        with self._db._connection() as conn:
            conn.execute(
                """INSERT INTO decision_records
                   (id, decision_text, rationale, alternatives, owner, review_date,
                    source_type, source_id, created_at, updated_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    record_id,
                    text,
                    rationale,
                    alternatives,
                    owner,
                    review_date,
                    source_kind,
                    source,
                    now,
                    now,
                ),
            )
            row = conn.execute(
                "SELECT * FROM decision_records WHERE id = ? AND deleted = 0", (record_id,)
            ).fetchone()
        assert row is not None
        return self._record_dict(row)

    def create_from_meeting(self, principal: Any, decision_id: str) -> dict[str, Any]:
        """Mint a record from a meeting-derived decision."""
        decision = self._db.decisions.get(decision_id)
        if decision is None:
            raise KeyError(str(decision_id or "").strip())
        existing = self._record_for_source("meeting", decision.id)
        if existing is not None:
            return existing

        record = self.create(
            principal,
            decision_text=decision.text,
            rationale=decision.rationale,
            source_type="meeting",
            source_id=decision.id,
        )
        # A segment is precision evidence, not a prerequisite for minting the
        # record.  Keep its absence honest when the decision's moment cannot
        # be resolved from the current transcript.
        try:
            moment = self._db.decisions.resolve_decision_moment(decision.id)
        except Exception:
            moment = None
        sources: list[tuple[str, str]] = [
            ("meeting", decision.source_meeting_id),
            ("artifact", decision.source_artifact_id),
        ]
        if moment is not None:
            sources.append(("segment", str(moment.segment_id)))
        self._add_sources(record["id"], tuple(sources))
        return record

    def create_from_desk(self, principal: Any, desk_decision_id: str) -> dict[str, Any]:
        """Mint a record from an authored desk decision."""
        decision = self._db.desk_decisions.get(desk_decision_id)
        if decision is None:
            raise KeyError(str(desk_decision_id or "").strip())
        existing = self._record_for_source("desk", decision.id)
        if existing is not None:
            return existing

        decision_text = decision.decision_markdown.strip()
        if not decision_text:
            raise ValueError("desk decision decision_markdown is required")
        rationale = self._join_text(
            decision.context_markdown, decision.consequences_markdown
        )
